"""Show context-sensitive water activation and all-input contribution removals."""
from pathlib import Path
from html import escape
import json,math,hashlib,shutil,importlib.util
HERE=Path(__file__).resolve().parent;OUT=HERE.parents[1]/'results/2026-11-12-water-ice-probe'
s=json.loads((OUT/'analysis.json').read_text());r=json.loads((OUT/'results.json').read_text());spec=importlib.util.spec_from_file_location('audit',HERE/'analyze.py');audit=importlib.util.module_from_spec(spec);spec.loader.exec_module(audit)
probe=[c for c in s['cases'] if not c['calibration']];assert len(probe)==6 and all(c['native_correct'] for c in probe)
assert all(not x['response_changed'] for x in s['rows'] if not x['calibration'])
scale=max(.5,math.ceil(max(t['natural_gate'] for c in r['cases'] for t in c['zero']['trace'] if t['context']=='generation')*2)/2)
def percent(x):
 if x is None:return '—'
 return (format(100*x,'.2e') if 0<100*x<.001 else format(100*x,'.4f'))+'%'
def trace(v,phase):return [t for t in v['trace'] if t['context']=='generation' and t['phase']==phase]
def heat(tr,removed=set(),after=False):
 out=[]
 for t in tr:
  edited=t['phase']=='input' and t['position'] in removed;g=0 if edited and after else t['natural_gate'];opacity=min(.88,.2+.68*g/scale) if g>0 else 0;word=escape(t['token']).replace('\n','↵\n').replace(' ','·')
  title=f"Token {t['position']}; ID {t['token_id']}; {t['phase']}; raw {t['raw']:.6f}; native gate {t['natural_gate']:.6f}; displayed gate {g:.6f}; {'removed' if edited else 'unedited'}"
  out.append(f"<span class='token {'edited' if edited else ''}' title='{escape(title,quote=True)}' style='background:rgba(229,113,72,{opacity})'>{word}</span>")
 return ''.join(out)
summary=[];cards=[]
for c in probe:
 raw=next(x for x in r['cases'] if x['id']==c['id']);v=next(x for x in raw['runs'] if x['scope']=='off-all');row=next(x for x in s['rows'] if x['id']==c['id'] and x['scope']=='off-all');last=next(x for x in s['rows'] if x['id']==c['id'] and x['scope']=='off-last');removed=set(row['edited_positions']);brief=(c['expected']+' …') if c['native_stop']=='token_limit' else c['native_response']
 summary.append(f"<tr><td><a href='#{c['id']}'>{escape(c['prompt'])}</a></td><td>{len(c['input_positive'])}</td><td>{len(c['response_positive'])}</td><td>{escape(brief)} → {escape(brief)}</td><td>{percent(row['native_p_expected'])} → {percent(row['off_p_expected'])}</td></tr>")
 positions=', '.join(str(t['position'])+' '+repr(t['token'])+' (gate '+format(t['gate'],'.6f')+')' for t in c['input_positive']) or 'none'
 cards.append(f'''<article class="card" id="{c['id']}"><div class="card-head"><h3>{escape(c['id'])}</h3><span class="badge">Native expected answer passes</span></div><p class="query">{escape(c['prompt'])}</p><p class="status-note">Native positive input positions: {escape(positions)}. Native positive response positions: {len(c['response_positive'])}.</p><h4>Full native input · T2375 gate heatmap</h4><p class="legend">Orange = positive post-threshold gate, on a shared 0–{scale:.2f} scale. Blue outlines mark the positive input contributions removed in all-input off. Spaces are dots and line breaks ↵. Hover for exact token ID, position, raw encoder value and gate.</p><div class="tokens input-tokens">{heat(trace(raw['zero'],'input'),removed)}</div><details><summary>Show input after contribution removal</summary><div class="tokens input-tokens">{heat(trace(raw['zero'],'input'),removed,True)}</div></details><div class="answers"><div class="answer"><h4>Native response</h4><div class="response">{escape(c['native_response'])}</div><p class="status-note">{'EOS' if c['native_stop']=='eos' else '32-token limit · initial answer only'}</p><div class="tokens">{heat(trace(raw['zero'],'response'))}</div></div><div class="answer"><h4>T2375 off · all input</h4><div class="response">{escape(v['native']['response'])}</div><p class="status-note">{row['edited_input_tokens']} positive input contributions removed · no generated edits · {'EOS' if row['off_stop']=='eos' else '32-token limit'}</p><div class="tokens">{heat(trace(v,'response'))}</div></div></div><p class="{'unrun' if not removed else 'status-note'}">{'No-op: the supplied input has no positive T2375 gate, so this condition subtracts zero.' if not removed else 'Effective removal: every positive supplied-input contribution was subtracted, and the response text remained unchanged.'}</p><div class="scroll"><table><thead><tr><th>Exact full-word prefix</th><th>Native</th><th>All-input off</th></tr></thead><tbody><tr><td>water</td><td>{percent(row['native_p_water'])}</td><td>{percent(row['off_p_water'])}</td></tr><tr><td>ice</td><td>{percent(row['native_p_ice'])}</td><td>{percent(row['off_p_ice'])}</td></tr><tr><td>Expected: {c['expected']}</td><td>{percent(row['native_p_expected'])}</td><td>{percent(row['off_p_expected'])}</td></tr></tbody></table></div><details><summary>Exact formatted prompt, final-token-only control and word-plus-EOS scores</summary><pre class="tokens">{escape(raw['case']['formatted_prompt'])}</pre><p>Final supplied-token off removes {last['edited_input_tokens']} positive contributions and responds: <code>{escape(last['off_response'])}</code>. P(expected word): {percent(last['native_p_expected'])} → {percent(last['off_p_expected'])}.</p><p>Expected word + EOS: {percent(row['native_p_expected_eos'])} → {percent(row['off_p_expected_eos'])}. These differ from word-prefix scores because the actual chat answers include a period.</p></details></article>''')
lit=next(c for c in r['cases'] if c['id']=='water-mentioned-chat');same=[t for t in lit['zero']['trace'] if t['context']=='generation' and t['token']=='Water'];assert len(same)==2 and same[0]['token_id']==same[1]['token_id'] and same[0]['natural_gate']>0 and same[1]['natural_gate']==0
same_rows=''.join(f"<tr><td>{t['phase']}</td><td>{t['position']}</td><td>{t['token_id']}</td><td>{t['raw']:.6f}</td><td>{t['natural_gate']:.6f}</td></tr>" for t in same)
cal=next(c for c in r['cases'] if c['id']=='month-calibration-11');off=next(v for v in cal['runs'] if v['scope']=='off-last')
calrows=''.join(f"<tr><td>{name}</td><td>{percent(audit.aggregate(cal['native'],name)['probability'])}</td><td>{percent(audit.aggregate(off,name)['probability'])}</td></tr>" for name in ['November','December'])
version=hashlib.sha256((OUT/'analysis.json').read_bytes()+(HERE/'render.py').read_bytes()).hexdigest()[:12]
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="only light"><meta name="darkreader-lock"><title>T2375: ice, water and context-sensitive activation</title><link rel="stylesheet" href="style.css?v={version}"></head><body><main><nav><a href="../2026-11-12-month-codewords/">← Month-codeword experiment</a><span>Qwen3-4B · L29–T2375 · 12 November 2026</span></nav><header><p class="eyebrow">Water questions · activation timing · input-only removal</p><h1>Does this gate help<br>the model answer “water”?</h1><p class="finding"><strong>The simple ice-melting questions do not activate T2375—not even while the model processes its water answers. Explicitly mentioning water in the input can activate it, but removing those input contributions keeps the tested answers.</strong></p><p>This is a six-prompt exploratory probe, plus the original month calibration. All native probe answers pass the frozen checks. We observe every supplied input and captured response token, then compare native output with removal at all positive input positions. A separate final-input-token condition is retained in the downloads.</p><div class="metrics"><div><strong>6 / 6</strong><span>native probe answers pass</span></div><div><strong>0 / 6</strong><span>probe response texts change</span></div><div><strong>2 / 6</strong><span>probes have active input contributions</span></div><div><strong>0 / 6</strong><span>probes have active response tokens</span></div></div></header><section><h2>All-input removal: answers and probabilities</h2><div class="scroll"><table><thead><tr><th>User question / completion</th><th>Active input positions</th><th>Active response positions</th><th>Native → off</th><th>P(expected word), native → off</th></tr></thead><tbody>{''.join(summary)}</tbody></table></div><p class="muted">“Active” means a positive post-JumpReLU gate, not merely a nonzero raw encoder value. The raw completion’s arrow summarizes its initial word; its full 32-token truncated continuation is below. Four no-activation probes are no-ops under input removal. They are not failed removals of an active feature.</p></section><section><h2>The same Water token, two contexts</h2><p>Within the water-mentioned chat case, both occurrences are exactly token ID <strong>{same[0]['token_id']}</strong>. The input <code>Water</code> activates; the model’s response <code>Water</code> does not. The saved threshold is <strong>{r['runtime']['threshold']:.6f}</strong>.</p><div class="scroll"><table><thead><tr><th>Where</th><th>Token position</th><th>Token ID</th><th>Raw encoder value</th><th>Post-threshold gate</th></tr></thead><tbody>{same_rows}</tbody></table></div><p>This directly demonstrates context dependence in the gate itself. It does not establish two distinct computational actions for the full transform.</p></section><section><h2>Exact prompts, token heatmaps and responses</h2><p class="muted">Response heatmaps show observed natural gates. No generated tokens are edited. In an autoregressive model, processing a token predicts the following token: activity on an already-completed water answer could not have caused that same word to be selected. Here, all six probe response traces have zero post-threshold gates.</p>{''.join(cards)}</section><section><h2>Implementation check: the month effect still reproduces</h2><p><code>the eleventh month of the year is</code> starts with November natively and December after removing the final-input contribution. Gate at <code> is</code>: 1.158554. Both long captures hit the 32-token limit; this is an initial-answer shift.</p><div class="scroll"><table><thead><tr><th>Answer prefix</th><th>Native</th><th>Gate off</th></tr></thead><tbody>{calrows}</tbody></table></div><details><summary>Full month-calibration responses</summary><div class="answers"><div class="answer"><h4>Native</h4><div class="response">{escape(cal['native']['native']['response'])}</div></div><div class="answer"><h4>Final-input off</h4><div class="response">{escape(off['native']['response'])}</div></div></div></details></section><section><h2>What this supports</h2><p>“Water-related activation” is not equivalent to a general water-answer detector. The basic ice-to-water questions are answered without any positive T2375 gate in these captures. Two effective removals of explicit input-water contributions leave the water/ice answers intact, with very small probability changes. This does not show a general loss of water knowledge, identify the transform’s full computation, or prove a purely lexical mechanism.</p><details><summary>Method, scope and precision</summary><p>Pinned native Qwen3-4B BF16 and L29 MOLT files, greedy decoding, chat thinking off, eager attention, TF32 disabled, 32-token limit. The observer reads the L29 post-attention residual before native RMSNorm. Standardize with the checkpoint input mean/std, compute the natural JumpReLU gate and low-rank operator, and subtract their product in native MLP-output units. The edit is FP32 followed by one BF16 cast. All native subsequent computation remains; no full MLP replacement and no generated/candidate-token edits.</p><p>Native and zero/observer results match exactly for all eight cases. Native competence is hash-locked before nonzero edits. The independent CPU audit checks gate/operator reconstruction, selected masks, actual contribution changes, exact BF16 rounding and complete-word probabilities at {s['audit']['independent_vector_samples']} saved vector positions. Four positive position contributions are removed across sixteen scope conditions (including month calibration); twelve conditions target only zero gates.</p><p>Word-prefix scores sum prescribed lowercase/titlecase variants with zero/one leading space, deduplicated by token sequence. Complete multi-token words are scored. These exclude punctuation, EOS, synonyms, longer answer phrases and alternative tokenizations. Word-plus-EOS scores are separate; the actual chat responses end in a period. Percentages are rounded; raw numerical values are retained. A few FP32-based sums differ from one by a few parts in 100 million. Raw completion competence concerns the initial answer word; chat competence accepts the expected one-word answer with terminal punctuation.</p><p>This is a small exploratory probe with easy questions, no unrelated norm-matched active-transform control, and no claim about water behavior in other contexts.</p></details><p class="source-links"><a href="probabilities.csv">All scopes and probabilities</a><a href="analysis.json">Timing and independent audit</a><a href="protocol.json">Frozen prompts</a><a href="baseline-lock.json">Pre-ablation baseline lock</a><a href="results.json">Full captures</a><a href="source/run.py">Inference source</a><a href="source/analyze.py">Audit source</a></p></section><footer>Input/response timing is explicit; zero activation and zero edits are retained. Layer and token IDs are zero-based.</footer></main></body></html>'''
(OUT/'index.html').write_text(html);shutil.copy2(HERE.parent/'month-codewords-20261112/web/style.css',OUT/'style.css');(OUT/'source').mkdir(exist_ok=True)
for n in ['run.py','analyze.py','render.py']:shutil.copy2(HERE/n,OUT/'source'/n)
print('Built six prompt heatmaps, response comparisons, same-token contrast and calibration.')

(OUT/'section.html').write_text('<section id="water-ice-probe"><p class="eyebrow">Follow-up · water and context</p><h2>Does T2375 help answer water?</h2><p>Three basic ice-melting prompts have no positive input or response activation. Explicit input-water mentions can activate the gate; removing those contributions keeps the tested answers. The exact same Water token activates in the input and not in the response.</p><p><a href="../2026-11-12-water-ice-probe/">Six prompts, token heatmaps, responses and probabilities →</a></p></section>\n')
